{
  "name": "短波红外高光谱相机帧采集单元",
  "name_en": "SWIR Hyperspectral Camera Frame Grabber",
  "manufacturer": "Specim",
  "description": "用于接收并采集短波红外高光谱相机图像数据的帧采集单元，通常与 Specim SWIR 成像系统配合使用。在实验室中可用于连续获取样品的短波红外高光谱数据流，服务于成像、检测与分析实验。",
  "description_en": "A frame grabber unit used to receive and acquire image data from a short-wave infrared hyperspectral camera, typically as part of a Specim SWIR imaging system. In laboratory use, it supports continuous collection of SWIR hyperspectral data streams for imaging, inspection, and analysis experiments.",
  "tag_hints": [
    "SWIR hyperspectral imaging",
    "frame grabbing",
    "camera data acquisition",
    "TCP/IP image streaming",
    "spectral imaging",
    "continuous image capture"
  ],
  "actions": [
    {
      "action_name": "auto-run",
      "description": "启动帧采集。",
      "description_en": "Start frame acquisition."
    },
    {
      "action_name": "auto-stop",
      "description": "停止帧采集。",
      "description_en": "Stop frame acquisition."
    },
    {
      "action_name": "auto-running",
      "description": "获取帧采集是否正在运行。",
      "description_en": "Get whether frame acquisition is running."
    }
  ]
}

